func agreementRawProseP0Physical(body string, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementEscapedClosingDiagnosticOwner, bool) {
	var owners []agreementEscapedClosingDiagnosticOwner
	physical, ok := agreementProseP1Physical(body, check, tree, target)
	if !ok || !tree.Valid {
		return nil, false
	}
	for oi := range physical {
		o := physical[oi]
		owners = append(owners, agreementEscapedClosingDiagnosticOwner(o))
	}
	return owners, len(owners) > 0
}
func agreementRawProseP0Producers(t *testing.T, body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) (physicalFields, diagnosticFields []agreementEscapedClosingDiagnosticOwner, targetChanges []agreementMixedRename, projectedBody string, valid bool) {
	t.Helper()
	rawTarget := target + "\\"
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementRawProseP0Physical(body, check, &tree, target)
	if !ok {
		return nil, nil, nil, "", false
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return nil, nil, nil, "", false
	}
	var owners []agreementEscapedClosingDiagnosticOwner
	var changes []agreementMixedRename
	whole := []byte(body)
	used := map[int]bool{}
	for oi := range physical {
		owner := &physical[oi]
		private, oneChanges, valid := agreementEscapedClosingDiagnosticPrivateSingle(body, rawTarget, target, owner, check)
		if !valid {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		privateParts, validParts := agreementCodeWindowParts(pr.HTML)
		if !validParts || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, privateParts) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		unique := true
		for di := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[di], pr.Diagnostics[di]) {
				continue
			}
			if index >= 0 {
				unique = false
				break
			}
			index = di
		}
		if !unique || index < 0 || used[index] {
			continue
		}
		a, b := raw.Diagnostics[index], pr.Diagnostics[index]
		change := oneChanges[0]
		if a.Section != "" || a.Kind != render.DiagWikilinkBroken || a.Target != rawTarget || b.Target != change.New+"\\" || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, strconv.Quote(rawTarget), strconv.Quote(change.New+"\\")) {
			continue
		}
		used[index] = true
		owners = append(owners, *owner)
		changes = append(changes, change)
		copy(whole[change.Span.Start:change.Span.Stop], change.New)
	}
	return physical, owners, changes, string(whole), len(owners) > 0
}

func agreementRawProseP0Private(body string, owners []agreementEscapedClosingDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementRawProseP0Physical(body, check, &tree, "A")
	if !ok || len(owners) == 0 {
		return "", nil, false
	}
	whole := []byte(body)
	changes := []agreementMixedRename{}
	seen := map[int]bool{}
	for oi := range owners {
		o := owners[oi]
		if seen[o.Field] || !slices.Contains(physical, o) {
			return "", nil, false
		}
		seen[o.Field] = true
		_, one, valid := agreementEscapedClosingDiagnosticPrivateSingle(body, "A\\", "A", &o, check)
		if !valid || len(one) != 1 {
			return "", nil, false
		}
		c := one[0]
		copy(whole[c.Span.Start:c.Span.Stop], c.New)
		changes = append(changes, c)
	}
	return string(whole), changes, true
}
func agreementRawProseP0Projection(r *agreementRawProseP0Declaration, before, after []agreementFailure) bool {
	if r == nil || !maps.Equal(agreementMixedCurrent(before), r.BeforeSignatures) || !maps.Equal(agreementMixedCurrent(after), r.AfterSignatures) || len(r.RawOwners) != r.Fields || r.Fields < 1 || len(r.Changes) != r.Fields || len(r.RawSingles) != r.Fields {
		return false
	}
	var selected *agreementFailure
	for i := range before {
		if agreementSignature(&before[i]) == r.Selected {
			if selected != nil {
				return false
			}
			selected = &before[i]
		}
	}
	if selected == nil || selected.Tuple.Target != r.Target || selected.Multiplicity != r.Fields {
		return false
	}
	return agreementEscapedClosingDiagnosticSignedProjection(before, after, &r.Page, r.Targets, selected, r.Fields, r.Active, r.Body, r.Private, r.Changes)
}
func agreementRawProseP0Difference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Target != "A\\" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementRawProseP0Declarations()
	for i := range records {
		r := &records[i]
		if r.Body != c.Body {
			continue
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, ok := agreementCodeWindowParts(html)
		physical, pok := agreementRawProseP0Physical(c.Body, &check, &tree, "A")
		private, changes, valid := agreementRawProseP0Private(c.Body, r.RawOwners, &check)
		if agreementSignature(f) != r.Selected || html != r.HTML || !ok || !pok || !valid || private != r.Private || !cmp.Equal(changes, r.Changes) || !cmp.Equal(physical, r.RawPhysical) || !cmp.Equal(native, r.Native) || !cmp.Equal(check, r.Check) || !cmp.Equal(tree, r.Tree) || !cmp.Equal(parts, r.Parts) || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !cmp.Equal(judge.LinkTargets(c.Body), r.Targets) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), r.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), r.HTMLSites) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(c.Body), r.Removed) || !agreementRawProseP0Projection(r, failures, r.After) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}
func TestAgreementRawProseP0OwnedSource(t *testing.T) {
	records := agreementRawProseP0Declarations()
	if len(records) != 2 {
		t.Fatal("caught: whole raw prose diagnostic declaration set")
	}
	for i := range records {
		r := &records[i]
		t.Run(r.Case, func(t *testing.T) {
			native := agreementNativeOwnerReading(r.Body)
			check := agreementNativeCheckReading(r.Body, native)
			physical, owners, changes, private, valid := agreementRawProseP0Producers(t, r.Body, "A", native, &check)
			if !valid || !cmp.Equal(physical, r.RawPhysical) || !cmp.Equal(owners, r.RawOwners) || !cmp.Equal(changes, r.Changes) || private != r.Private {
				t.Fatal("caught: complete raw prose physical producers and target intervals")
			}
			raw, page, before := agreementConsumedTableCellFailures(t, r.Body)
			pr, pp, after := agreementConsumedTableCellFailures(t, r.Private)
			parts, ok := agreementCodeWindowParts(raw.HTML)
			pParts, pok := agreementCodeWindowParts(pr.HTML)
			if !ok || !pok || raw.HTML != r.HTML || pr.HTML != r.PrivateHTML || raw.HTML != pr.HTML || !cmp.Equal(page, r.Page) || !cmp.Equal(pp, r.PrivatePage) || !cmp.Equal(page, pp) || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !cmp.Equal(pr.Diagnostics, r.PrivateDiagnostics) || !cmp.Equal(parts, r.Parts) || !cmp.Equal(pParts, r.PrivateParts) || !agreementRawProseP0Projection(r, before, after) {
				t.Fatal("caught: whole raw prose public diagnostics and signed ledgers")
			}
			if !cmp.Equal(native, r.Native) || !cmp.Equal(check, r.Check) || !cmp.Equal(agreementNativeOwnerReading(r.Private), r.PrivateNative) || !cmp.Equal(agreementNativeCheckReading(r.Private, r.PrivateNative), r.PrivateCheck) || !cmp.Equal(agreementNativeProseAddressTreeReading(r.Body, nil), r.Tree) || !cmp.Equal(agreementNativeProseAddressTreeReading(r.Private, nil), r.PrivateTree) || !cmp.Equal(agreementNativeCodePayloadSites(r.Body), r.Sites) || !cmp.Equal(agreementNativeCodePayloadSites(r.Private), r.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(r.Body), r.HTMLSites) || !cmp.Equal(agreementNativeHTMLAddressSites(r.Private), r.HTMLSites) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(r.Body), r.Removed) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(r.Private), r.PrivateRemoved) || !cmp.Equal(judge.LinkTargets(r.Body), r.Targets) || !cmp.Equal(judge.LinkTargets(r.Private), r.PrivateTargets) {
				t.Fatal("caught: whole raw prose original and private reader declarations")
			}
			for _, single := range r.RawSingles {
				sr, sp := agreementIsolatedPage(t, agreementCase{Body: single.Body})
				part, good := agreementCodeWindowParts(sr.HTML)
				if !good || sr.HTML != r.HTML || !cmp.Equal(sp, r.Page) || !cmp.Equal(part, r.Parts) || !cmp.Equal(sr.Diagnostics, single.Diagnostics) || !cmp.Equal(agreementNativeOwnerReading(single.Body), r.Native) || !cmp.Equal(agreementNativeProseAddressTreeReading(single.Body, nil), r.Tree) {
					t.Fatal("caught: independent raw prose single field observations")
				}
			}
			count := 0
			for fi := range before {
				f := &before[fi]
				if agreementSignature(f) == r.Selected {
					count++
					k, a, w := agreementRawProseP0Difference(agreementCase{Body: r.Body}, f, raw.HTML, &page, raw.Diagnostics, before)
					if k != "debt" || a != "#1011 stage 5" || w != "page-diagnostic" {
						t.Fatal("caught: raw prose source bound authority")
					}
				}
			}
			if count != 1 {
				t.Fatal("caught: unique raw prose selection")
			}
		})
	}
}
func TestAgreementRawProseP0OwnedRefusals(t *testing.T) {
	for _, r := range agreementRawProseP0Declarations() {
		t.Run(r.Case, func(t *testing.T) {
			raw, page, fs := agreementConsumedTableCellFailures(t, r.Body)
			var selected agreementFailure
			for _, f := range fs {
				if agreementSignature(&f) == r.Selected {
					selected = f
				}
			}
			refuse := func(c agreementCase, f *agreementFailure, html string, p *agreementHTML, d []render.Diagnostic, failures []agreementFailure) {
				t.Helper()
				k, a, w := agreementRawProseP0Difference(c, f, html, p, d, failures)
				if k != "" || a != "" || w != "" {
					t.Fatal("caught: exact raw prose membership and complete public context")
				}
			}
			refuse(agreementCase{Body: r.Body}, nil, raw.HTML, &page, raw.Diagnostics, fs)
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, nil, raw.Diagnostics, fs)
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity += "!" }, func(f *agreementFailure) { f.Direction = "page-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.Target = "q\\" }, func(f *agreementFailure) { f.Tuple.SourceRole = "image" }, func(f *agreementFailure) { f.Tuple.Section = "A" }, func(f *agreementFailure) { f.Tuple.State = "other" }, func(f *agreementFailure) { f.Fragment = "a" }, func(f *agreementFailure) { f.Cut = "text" }, func(f *agreementFailure) { f.PagePresent = true }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }}
			for _, change := range changes {
				f := selected
				change(&f)
				refuse(agreementCase{Body: r.Body}, &f, raw.HTML, &page, raw.Diagnostics, fs)
			}
			refuse(agreementCase{Body: r.Body + "!"}, &selected, raw.HTML, &page, raw.Diagnostics, fs)
			refuse(agreementCase{Body: r.Body, Title: "outside"}, &selected, raw.HTML, &page, raw.Diagnostics, fs)
			refuse(agreementCase{Body: r.Body, Companions: capturedBodies{"outside.md": "text"}}, &selected, raw.HTML, &page, raw.Diagnostics, fs)
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML+"!", &page, raw.Diagnostics, fs)
			changedPage := page
			changedPage.Blocks = append(slices.Clone(page.Blocks), "^outside")
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &changedPage, raw.Diagnostics, fs)
			changedDiags := append(slices.Clone(raw.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, changedDiags, fs)
			for i := range fs {
				missing := slices.Delete(slices.Clone(fs), i, i+1)
				refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, missing)
				changed := slices.Clone(fs)
				changed[i].Multiplicity++
				refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, changed)
			}
		})
	}
}
